// amplify_outputs.json is generated by `npx ampx sandbox` (local) or
// `npx ampx pipeline-deploy` (Amplify Hosting). scripts/ensure-amplify-outputs.mjs
// writes a stub when it is missing so the import always resolves.
import outputs from "@/amplify_outputs.json";

type AmplifyOutputs = Record<string, unknown> & {
  auth?: { user_pool_id?: string; identity_pool_id?: string };
  storage?: { bucket_name?: string; aws_region?: string };
  custom?: { mediaBucketName?: string; workspaceBucketName?: string; region?: string };
  _stub?: boolean;
};

export const amplifyOutputs = outputs as AmplifyOutputs;

/** True when a real Cognito user pool is configured. */
export const hasAmplifyAuth = Boolean(amplifyOutputs.auth?.user_pool_id);
